// Vector tilesets generated by scripts/make-vtiles.js, written to output/vtiles/{key}{yy}.mbtiles.
//
// Tilesets are defined by structure only. A version is made for every year that any of
// its source geographies has boundaries for (in config/source-files.js), named after that
// year, and each source uses its latest year up to then. Eg. "la" for 2024 combines
// ltla 2023, cty 2023 and cauth 2024.
//
// Existing .mbtiles files are skipped, so generate specific tilesets with eg.
//   npm run make-vtiles -- --geo wd --year 2025
//
//   sources: geographies to combine, each as its own layer (default: just the tileset's
//            own key, as one layer called "boundaries")
//   minzoom: lowest zoom level to generate
//   metadata: extra attributes, made for each version. {flag: "cauth"} sets cauth=true on
//             areas whose parent in that year is one of the tileset's "cauth" areas
import geo_config from "./geo-config.js";

const tilesets = [
  {
    key: "la",
    sources: [{key: "ltla"}, {key: "cty"}, {key: "cauth"}],
    // Mark local authorities and counties in a combined authority in that year
    metadata: {flag: "cauth"}
  },
  {key: "wpc", minzoom: 4},
  {
    key: "sen",
    sources: [{key: "sener", layer: "region"}, {key: "senc", layer: "constituency"}]
  },
  {key: "wd", minzoom: 6},
  {key: "par", minzoom: 6},
  {key: "msoa", minzoom: 6},
  {key: "lsoa", minzoom: 7}
  // OA tiles are made by make-oa-vtiles instead, which merges small OAs into their
  // parents at low zooms. Both write output/vtiles/oa21.mbtiles, so a plain {key: "oa"}
  // tileset is left out.
];

// One entry per tileset and year, with the year each source uses
export function expandTilesets(tilesets, yearsOf) {
  return tilesets.flatMap(({sources, ...tileset}) => {
    const resolved = sources || [{key: tileset.key}];
    const years = [...new Set(resolved.flatMap(s => yearsOf(s.key)))].sort((a, b) => a - b);
    return years
      .map(year => ({
        ...tileset,
        year,
        sources: resolved.map(s => {
          const sourceYears = yearsOf(s.key).filter(y => y <= year);
          return sourceYears.length ? {...s, year: Math.max(...sourceYears)} : null;
        })
      }))
      // Skip years before every source has boundaries
      .filter(t => t.sources.every(s => s));
  });
}

export default expandTilesets(tilesets, (key) => geo_config.find(g => g.key === key).years);
